challenge.code:
const P = ctx.params;
const head = ctx.text('tap the field each rule belongs on', { size: 12, color: ctx.colors.dim });
head.anchor.set(0.5); head.x = ctx.width / 2; head.y = 16;
ctx.stage.addChild(head);
const why = ctx.text('', { size: 11, color: ctx.colors.warn });
why.anchor.set(0.5); why.x = ctx.width / 2; why.y = ctx.height - 10;
ctx.stage.addChild(why);
const cellW = ctx.width / 2;
P.fields.forEach((f, i) => {
  const c = ctx.chip(f.label, { color: 0x0c2a31, textColor: 0xd7fbf4, stroke: ctx.colors.g2, minWidth: Math.min(200, cellW - 26), size: 12, padY: 12, radius: 12 });
  c.x = cellW * (i % 2) + cellW / 2;
  c.y = 58 + Math.floor(i / 2) * 86;
  c.homeX = c.x;
  c.fid = f.id;
  c.slots = 0;
  c.eventMode = 'static';
  c.cursor = 'pointer';
  c.on('pointertap', () => drop(c));
  ctx.stage.addChild(c);
});
let idx = 0, done = 0, miss = 0, hand = null, busy = false;
ctx.api.setGoal('0 / ' + P.rules.length);
function spawn() {
  const r = P.rules[idx];
  if (!r) return;
  const c = ctx.chip(r.label, { color: ctx.colors.g1, textColor: 0x04211d, size: 14, padY: 10, radius: 11 });
  c.x = ctx.width / 2;
  c.y = ctx.height - 38;
  c.rule = r;
  ctx.stage.addChild(c);
  gsap.fromTo(c.scale, { x: 0.6, y: 0.6 }, { x: 1, y: 1, duration: 0.3, ease: 'back.out' });
  hand = c;
}
function drop(card) {
  if (busy || !hand) return;
  const r = hand.rule;
  if (r.field === card.fid) {
    busy = true;
    const chip = hand;
    hand = null;
    const ty = card.y + 26 + card.slots * 17;
    card.slots += 1;
    gsap.to(chip, { x: card.x, y: ty, duration: 0.34, ease: 'back.out' });
    gsap.to(chip.scale, { x: 0.6, y: 0.6, duration: 0.34 });
    gsap.to(card.scale, { x: 1.07, y: 1.07, duration: 0.12, onComplete: () => gsap.to(card.scale, { x: 1, y: 1, duration: 0.2, ease: 'back.out' }) });
    done += 1;
    idx += 1;
    why.text = '';
    ctx.api.setScore(done);
    ctx.api.setGoal(done + ' / ' + P.rules.length);
    if (done >= P.rules.length) { ctx.api.win('Every rule landed on a field whose value it can actually read.'); return; }
    gsap.delayedCall(0.42, () => { busy = false; spawn(); });
  } else {
    miss += 1;
    why.text = r.label + ' ' + r.why;
    const x0 = card.homeX;
    gsap.to(card, { x: x0 - 9, duration: 0.06, onComplete: () => gsap.to(card, { x: x0 + 9, duration: 0.09, onComplete: () => gsap.to(card, { x: x0, duration: 0.14, ease: 'back.out' }) }) });
    gsap.fromTo(hand.scale, { x: 1.16, y: 1.16 }, { x: 1, y: 1, duration: 0.28, ease: 'back.out' });
    if (miss >= 3) ctx.api.fail('Three rules attached to a field they cannot read. Match the validator to the value type.');
  }
}
spawn();

