$saved = null

function onSubmit(values) {
  $save.mutate({ body: values })
}

$save = $mutation({ url: "https://api.example.com/signup", method: "POST" })
$save.onDone = () => { $saved = "Welcome aboard, check your inbox."; signup.reset() }

signup = $form({
  values: { name: "", email: "" },
  rules: {
    name: [$util.rules.required()],
    email: [$util.rules.required(), $util.rules.email()]
  },
  onSubmit: onSubmit
})

$app(Card([
  SectionHeader("Create your account"),
  Show($saved, { children: Callout("Saved", { tone: "success", description: $saved, compact: true }) }),
  ValidationSummary(signup.errors),
  FormSection("About you", [
    FormControl("Name", Input("name", { value: signup.values.name, error: signup.errors.name, onBlur: () => signup.touch("name") })),
    FormControl("Work email", Input("email", { type: "email", value: signup.values.email, error: signup.errors.email, onBlur: () => signup.touch("email") }))
  ]),
  Buttons([
    Button("Create account", { variant: "primary", loading: $save.loading, disabled: signup.submitting, action: () => signup.handleSubmit() }),
    Button("Reset", { variant: "ghost", action: () => signup.reset() })
  ])
]))

